const config = $('Configuration').item.json;
const sprintInfo = $('Extract Sprint Details').item.json;
const response = $input.item.json;
const issues = response.issues || [];

const thresholdHours = Number(config.inProgressThresholdHours || 48);
const sprintStart = new Date(sprintInfo.sprintStartDate);
const now = new Date();

const flaggedIssues = [];
let scopeCreepCount = 0;
let stagnantCount = 0;

for (const issue of issues) {
  const key = issue.key;
  const summary = issue.fields.summary;
  const assignee = issue.fields.assignee ? issue.fields.assignee.displayName : 'Unassigned';
  const created = new Date(issue.fields.created);
  const currentStatus = issue.fields.status ? issue.fields.status.name : 'Unknown';
  const issueUrl = 'https://' + config.jiraDomain + '.atlassian.net/browse/' + key;

  if (sprintStart && created > sprintStart) {
    scopeCreepCount++;
    flaggedIssues.push({
      key: key,
      summary: summary,
      assignee: assignee,
      url: issueUrl,
      reason: 'Scope Creep',
      detail: 'Added to the sprint on ' + created.toISOString().split('T')[0] + ', after sprint planning (sprint started ' + sprintStart.toISOString().split('T')[0] + ').'
    });
  }

  if (currentStatus === 'In Progress' && issue.changelog && Array.isArray(issue.changelog.histories)) {
    const histories = [...issue.changelog.histories].sort(function(a, b) { return new Date(a.created) - new Date(b.created); });
    let lastTransitionToInProgress = null;

    for (const history of histories) {
      for (const item of history.items) {
        if (item.field === 'status' && item.toString === 'In Progress') {
          lastTransitionToInProgress = new Date(history.created);
        }
      }
    }

    if (lastTransitionToInProgress) {
      const hoursInProgress = (now - lastTransitionToInProgress) / (1000 * 60 * 60);
      if (hoursInProgress > thresholdHours) {
        stagnantCount++;
        flaggedIssues.push({
          key: key,
          summary: summary,
          assignee: assignee,
          url: issueUrl,
          reason: 'Stuck In Progress',
          detail: 'In "In Progress" for ' + Math.round(hoursInProgress) + ' hours (threshold: ' + thresholdHours + 'h). Last moved on ' + lastTransitionToInProgress.toISOString().split('T')[0] + '.'
        });
      }
    }
  }
}

return [{
  json: {
    sprintName: sprintInfo.sprintName,
    sprintStartDate: sprintInfo.sprintStartDate,
    totalIssues: issues.length,
    flaggedCount: flaggedIssues.length,
    scopeCreepCount: scopeCreepCount,
    stagnantCount: stagnantCount,
    flaggedIssues: flaggedIssues
  }
}];

